package org.mockito.internal.util.reflection;

import java.io.*;
import java.lang.reflect.Field;
import java.lang.reflect.ParameterizedType;
import java.lang.reflect.Type;
import java.math.*;
import java.util.*;
import java.util.List;
import org.junit.*;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.mockito.Mockito.when;

@RunWith(MockitoJUnitRunner.class)
public class GenericMaster_getGenericType_TriageGen0Test {

    private final GenericMaster genericMaster = new GenericMaster();

    @Mock
    private Field field;

    @Mock
    private ParameterizedType parameterizedType;

    @Test
    public void testGetGenericType_WithParameterizedType() throws NoSuchFieldException {
        // Arrange
        Type actualType = String.class;
        when(field.getGenericType()).thenReturn(parameterizedType);
        when(parameterizedType.getActualTypeArguments()).thenReturn(new Type[]{actualType});

        // Act
        Class<?> result = genericMaster.getGenericType(field);

        // Assert
        assertEquals(String.class, result);
    }

    @Test
    public void testGetGenericType_WithNullGenericType() throws NoSuchFieldException {
        // Arrange
        when(field.getGenericType()).thenReturn(null);

        // Act
        Class<?> result = genericMaster.getGenericType(field);

        // Assert
        assertEquals(Object.class, result);
    }

    @Test
    public void testGetGenericType_WithNonParameterizedType() throws NoSuchFieldException {
        // Arrange
        Type rawType = Integer.class;
        when(field.getGenericType()).thenReturn(rawType);

        // Act
        Class<?> result = genericMaster.getGenericType(field);

        // Assert
        assertEquals(Object.class, result);
    }

    @Test
    public void testGetGenericType_WithList() throws NoSuchFieldException {
        // Arrange
        // Simulating List<Double>
        Type actualType = Double.class;
        when(field.getGenericType()).thenReturn(parameterizedType);
        when(parameterizedType.getActualTypeArguments()).thenReturn(new Type[]{actualType});

        // Act
        Class<?> result = genericMaster.getGenericType(field);

        // Assert
        assertEquals(Double.class, result);
    }
}
